import{_ as t,o,c as e,a2 as r}from"./chunks/framework.A5mep7Fe.js";const g=JSON.parse('{"title":"📝 01 · 简历撰写（AI 岗专属）","description":"","frontmatter":{},"headers":[],"relativePath":"09-面试实战/01-简历撰写.md","filePath":"09-面试实战/01-简历撰写.md","lastUpdated":1786806808000}'),l={name:"09-面试实战/01-简历撰写.md"};function i(n,a,s,h,c,d){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="📝-01-·-简历撰写-ai-岗专属" tabindex="-1">📝 01 · 简历撰写（AI 岗专属） <a class="header-anchor" href="#📝-01-·-简历撰写-ai-岗专属" aria-label="Permalink to &quot;📝 01 · 简历撰写（AI 岗专属）&quot;">​</a></h1><blockquote><p>简历是「入场券」。AI 岗简历最忌「堆名词、无证据」。本篇讲怎么写才过筛。</p></blockquote><hr><h2 id="一、ai-岗简历的「证据结构」" tabindex="-1">一、AI 岗简历的「证据结构」 <a class="header-anchor" href="#一、ai-岗简历的「证据结构」" aria-label="Permalink to &quot;一、AI 岗简历的「证据结构」&quot;">​</a></h2><p>每条经历都要回答：<strong>做了什么（Situation/Task）→ 怎么做的（Action）→ 结果多好（Result，带数字）</strong>。</p><p>❌ 差：「熟悉大模型，做过 RAG 项目」 ✅ 好：「设计并落地企业知识库 RAG 系统：用 LangChain+Milvus 实现混合检索（向量+BM25），召回率从 0.62 提升到 0.89，问答准确率提升 23%，服务 P99 延迟 1.2s，支撑 5 万员工内部问答」</p><h2 id="二、必备模块" tabindex="-1">二、必备模块 <a class="header-anchor" href="#二、必备模块" aria-label="Permalink to &quot;二、必备模块&quot;">​</a></h2><ol><li><strong>基本信息</strong>：姓名、联系方式、所在地、求职意向、GitHub/博客链接</li><li><strong>技能</strong>：分层写（精通/熟练/了解），别全写「精通」</li><li><strong>项目经历</strong>：2-4 个，STAR 化，突出 AI 相关</li><li><strong>工作/实习经历</strong>：量化产出</li><li><strong>教育</strong>：学校/专业/时间，相关课程可列</li><li><strong>加分项</strong>：论文/竞赛（Kaggle/KDD）、开源、技术博客、比赛名次</li></ol><h2 id="三、按岗位定制" tabindex="-1">三、按岗位定制 <a class="header-anchor" href="#三、按岗位定制" aria-label="Permalink to &quot;三、按岗位定制&quot;">​</a></h2><ul><li><strong>算法岗</strong>：突出模型/训练/论文/竞赛，写清「你改了什么、指标涨多少」</li><li><strong>开发岗</strong>：突出架构/工程/性能/落地，写清「系统规模、QPS、降本」</li><li><strong>AI 应用开发</strong>：突出「AI + 工程」结合，RAG/Agent/平台落地</li></ul><h2 id="四、常见雷区" tabindex="-1">四、常见雷区 <a class="header-anchor" href="#四、常见雷区" aria-label="Permalink to &quot;四、常见雷区&quot;">​</a></h2><ul><li>简历写「精通 Transformer」但推导不出注意力公式 → 必挂</li><li>项目全是「跟着教程做」无独立贡献 → 无说服力</li><li>技能清单堆 30 个名词无重点 → 显得浮</li><li>无数字、无结果 → 无法评估价值</li><li>一页塞满、无留白 → 阅读体验差（校招 1-2 页，社招 2-3 页）</li></ul><h2 id="五、ai-简历的「钩子」" tabindex="-1">五、AI 简历的「钩子」 <a class="header-anchor" href="#五、ai-简历的「钩子」" aria-label="Permalink to &quot;五、AI 简历的「钩子」&quot;">​</a></h2><p>在简历里埋「面试官会追问的点」：如「用 LoRA 微调把训练成本降 80%」——引导对话到你擅长处。</p><h2 id="六、高频追问-模拟" tabindex="-1">六、高频追问（模拟） <a class="header-anchor" href="#六、高频追问-模拟" aria-label="Permalink to &quot;六、高频追问（模拟）&quot;">​</a></h2><p><strong>Q：没大模型项目经验怎么办？</strong></p><blockquote><p>自己做一个：用开源模型搭 RAG/Agent（见 <code>08-AI应用开发</code>），写技术博客，开源到 GitHub。比空说「感兴趣」强十倍。</p></blockquote><p><strong>Q：转行怎么写简历？</strong></p><blockquote><p>突出可迁移能力（工程/数据/产品），用 AI 副项目证明学习力与落地力；诚实写背景，强调「为什么转、已做了什么」。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-面试流程与技巧">02-面试流程与技巧</a></p>',21)])])}const p=t(l,[["render",i]]);export{g as __pageData,p as default};
